import{_ as e,o as r,c as o,a6 as d}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"Error Code Registry","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/error-codes.md","filePath":"protocols/error-codes.md","lastUpdated":1771970963000}'),a={name:"protocols/error-codes.md"};function s(n,t,i,c,l,p){return r(),o("div",null,[...t[0]||(t[0]=[d('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/error-codes.md for this page in Markdown format</div><h1 id="error-code-registry" tabindex="-1">Error Code Registry <a class="header-anchor" href="#error-code-registry" aria-label="Permalink to “Error Code Registry”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Normative) <strong>Purpose</strong>: Canonical registry for all error codes across protocol layers.</p></blockquote><p>This document is the single source of truth for error codes. Specifications MUST reference this registry; they MUST NOT define codes inline.</p><h2 id="code-ranges" tabindex="-1">Code Ranges <a class="header-anchor" href="#code-ranges" aria-label="Permalink to “Code Ranges”">​</a></h2><table tabindex="0"><thead><tr><th>Range</th><th>Owner</th><th>Carrier</th><th>Purpose</th></tr></thead><tbody><tr><td>1000–1099</td><td>SBP</td><td>ErrorFrame</td><td>Frame/handshake/namespace faults</td></tr><tr><td>1100–1199</td><td>RPC</td><td>RpcError</td><td>Envelope/method/routing faults</td></tr><tr><td>1200–1999</td><td>Reserved</td><td>—</td><td>Future protocol extensions</td></tr><tr><td>2000+</td><td>App</td><td>RpcError</td><td>User-defined application errors</td></tr></tbody></table><p>Implementations MUST NOT define codes outside their owned range.</p><h2 id="transport-errors-local" tabindex="-1">Transport Errors (Local) <a class="header-anchor" href="#transport-errors-local" aria-label="Permalink to “Transport Errors (Local)”">​</a></h2><p>Transport errors are <strong>local-only</strong> and are <strong>NOT</strong> wire protocol errors. They describe why a local transport operation failed (connection refused, DNS failure, TLS error, timeout, etc.) and are never sent on the wire or carried in <code>ErrorFrame</code> or <code>RpcError</code>.</p><p>For the full transport error taxonomy, see <a href="./transport/errors">transport/errors.md</a>.</p><p><strong>TransportErrorKind values</strong> (reference):</p><table tabindex="0"><thead><tr><th>Kind</th><th>Retryable</th><th>Description</th></tr></thead><tbody><tr><td><code>connection_refused</code></td><td>Yes</td><td>Server not accepting connections</td></tr><tr><td><code>dns_failure</code></td><td>Yes</td><td>DNS resolution failed</td></tr><tr><td><code>tls_failure</code></td><td>No</td><td>TLS/SSL handshake or certificate error</td></tr><tr><td><code>timeout</code></td><td>Yes</td><td>Connection or operation timed out</td></tr><tr><td><code>network_offline</code></td><td>Yes</td><td>Network unavailable</td></tr><tr><td><code>abnormal_close</code></td><td>Yes</td><td>Connection dropped unexpectedly</td></tr><tr><td><code>message_too_large</code></td><td>No</td><td>Message exceeds size limit</td></tr><tr><td><code>policy_violation</code></td><td>No</td><td>CSP, CORS, or browser security policy</td></tr><tr><td><code>authentication_failed</code></td><td>No</td><td>Relay-level auth (NOT E2EE auth)</td></tr><tr><td><code>aborted</code></td><td>No</td><td>Explicit AbortSignal cancellation</td></tr><tr><td><code>subprotocol_mismatch</code></td><td>No</td><td>Subprotocol negotiation failed</td></tr><tr><td><code>transport_failure</code></td><td>Yes</td><td>Catch-all for unmapped errors</td></tr></tbody></table><blockquote><p><strong>Scope distinction</strong>:</p><ul><li><strong>Wire protocol errors</strong> (this document): Sent between peers, carried in <code>ErrorFrame</code> or <code>RpcError</code></li><li><strong>Transport errors</strong> (<a href="./transport/errors">transport/errors.md</a>): Local-only, describe transport layer failures, surfaced via <code>TransportError</code> class</li></ul></blockquote><h2 id="sbp-codes-1000–1099" tabindex="-1">SBP Codes (1000–1099) <a class="header-anchor" href="#sbp-codes-1000–1099" aria-label="Permalink to “SBP Codes (1000–1099)”">​</a></h2><p>Carried in <code>ErrorFrame.code</code>. These are protocol-level errors.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Fatality</th><th>Semantics</th></tr></thead><tbody><tr><td>1000</td><td>ProtocolViolation</td><td>Fatal</td><td>Generic protocol contract violation</td></tr><tr><td>1001</td><td>UnsupportedVersion</td><td>Fatal</td><td>Peer advertised incompatible version</td></tr><tr><td>1002</td><td>InvalidFrame</td><td>Contextual</td><td>Frame structure or encoding error</td></tr><tr><td>1003</td><td>UnsupportedFeature</td><td>Non-fatal</td><td>Feature reserved or requires capability exchange</td></tr></tbody></table><p><strong>Fatality rules</strong>:</p><ul><li><strong>Fatal</strong>: Receiver MUST close transport after emitting diagnostics</li><li><strong>Non-fatal</strong>: Continue processing subsequent frames</li><li><strong>Contextual</strong>: MAY be fatal if recovery is unsafe; otherwise continue</li></ul><p>See <a href="./sbp/errors">SBP Error Model</a> for sender/receiver contracts.</p><h2 id="rpc-codes-1100–1199" tabindex="-1">RPC Codes (1100–1199) <a class="header-anchor" href="#rpc-codes-1100–1199" aria-label="Permalink to “RPC Codes (1100–1199)”">​</a></h2><p>Carried in <code>RpcError.code</code> (envelope <code>t: &quot;E&quot;</code>). These are request-scoped errors that MUST NOT trigger transport close.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Semantics</th></tr></thead><tbody><tr><td>1100</td><td>InvalidEnvelope</td><td>Envelope structure or encoding error</td></tr><tr><td>1101</td><td>UnsupportedMethod</td><td>Method not recognized by handler</td></tr><tr><td>1102</td><td>CorrelationMismatch</td><td>Response cid does not match any pending request</td></tr><tr><td>1103</td><td>Timeout</td><td>Request timed out waiting for response</td></tr><tr><td>1104</td><td>EnvelopeMismatch</td><td>Envelope type incompatible with subject prefix</td></tr></tbody></table><p><strong>Key invariant</strong>: Routers MUST NOT use SBP <code>ErrorFrame</code> to represent handler timeouts. Timeouts MUST be delivered as <code>RpcError</code> responses.</p><h2 id="application-codes-2000" tabindex="-1">Application Codes (2000+) <a class="header-anchor" href="#application-codes-2000" aria-label="Permalink to “Application Codes (2000+)”">​</a></h2><p>User-defined codes for application-specific errors. Carried in <code>RpcError.code</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Semantics</th></tr></thead><tbody><tr><td>2000</td><td>ApplicationError</td><td>Catch-all for unspecified app errors</td></tr></tbody></table><p>Applications MAY define stable subcodes above 2000 for domain-specific errors.</p><h2 id="sbrp-control-codes" tabindex="-1">SBRP Control Codes <a class="header-anchor" href="#sbrp-control-codes" aria-label="Permalink to “SBRP Control Codes”">​</a></h2><p>SBRP uses a separate namespace (0x01xx–0x10xx) for relay control signaling. These are NOT error codes and are never carried in <code>ErrorFrame</code> or <code>RpcError</code>. See <a href="./sbrp/control-codes">SBRP Control Codes</a>.</p><h2 id="adding-new-codes" tabindex="-1">Adding New Codes <a class="header-anchor" href="#adding-new-codes" aria-label="Permalink to “Adding New Codes”">​</a></h2><p>New codes require:</p><ol><li>ADR documenting the need and semantics</li><li>Update to this registry</li><li>Update to <code>@sideband/protocol</code> or <code>@sideband/rpc</code> constants</li></ol><p>Reserved ranges (1200–1999) are allocated only by ADR.</p>',33)])])}const b=e(a,[["render",s]]);export{u as __pageData,b as default};
